Translate the following GNU C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;
const int INF = 1e7;
const int MAX_N = 12;
const int MAX_T = 62;
const int MAX_NODES = 210;
const int MAX_EDGES = 21000;

struct Edge {
    int v, w;
};

Edge edges[MAX_EDGES];
int adj[MAX_EDGES], head[MAX_NODES], edge_count;

void addEdge(int u, int v, int w) {
    edges[edge_count] = {v, w};
    adj[edge_count] = head[u];
    head[u] = edge_count++;

    edges[edge_count] = {u, 0};
    adj[edge_count] = head[v];
    head[v] = edge_count++;
}

int dist[MAX_NODES], queue_arr[MAX_NODES * 2], arc[MAX_NODES], gap[MAX_NODES], inq[MAX_NODES], pre[MAX_NODES];

int SAP(int s, int t) {
    memset(arc, -1, sizeof(arc));
    memset(pre, -1, sizeof(pre));
    int qf = 0, qr = 0;
    queue_arr[qr++] = t;
    inq[t] = 1;
    gap[0]++;
    dist[t] = 0;

    while (qf < qr) {
        int u = queue_arr[qf++];
        for (int i = head[u]; i != -1; i = adj[i]) {
            int v = edges[i].v;
            if (!inq[v]) {
                queue_arr[qr++] = v;
                inq[v] = 1;
                dist[v] = dist[u] + 1;
                gap[dist[v]]++;
                arc[v] = head[v];
            }
        }
    }

    int low = INF, u = s, ans = 0;
    pre[s] = s;

    while (dist[s] < t) {
        bool found = false;
        for (int& i = arc[u]; i != -1; i = adj[i]) {
            if (edges[i].w && dist[edges[i].v] + 1 == dist[u]) {
                found = true;
                low = min(low, edges[i].w);
                pre[edges[i].v] = u;
                u = edges[i].v;
                if (u == t) {
                    while (u != s) {
                        u = pre[u];
                        edges[arc[u]].w -= low;
                        edges[arc[u] ^ 1].w += low;
                    }
                    ans += low;
                    low = INF;
                }
                break;
            }
        }

        if (found) continue;

        int min_dist = t + 1;
        for (int i = head[u]; i != -1; i = adj[i]) {
            if (edges[i].w && min_dist > dist[edges[i].v]) {
                min_dist = dist[edges[i].v];
                arc[u] = i;
            }
        }

        gap[dist[u]]--;
        if (gap[dist[u]] == 0) return ans;
        dist[u] = min_dist + 1;
        gap[dist[u]]++;
        u = pre[u];
    }

    return ans;
}

char grid1[MAX_N][MAX_N], grid2[MAX_N][MAX_N];
int sci[MAX_N][MAX_N], ca[MAX_N][MAX_N], stone[MAX_T][MAX_N][MAX_N];
int dp[MAX_T][MAX_N][MAX_N][MAX_N][MAX_N];
int dirs[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
int n, t;

void expandStone() {
    for (int k = 1; k <= t; ++k) {
        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= n; ++j) {
                if (stone[k-1][i][j] == 1) {
                    stone[k][i][j] = 1;
                } else if (stone[k-1][i][j] == 2) {
                    stone[k][i][j] = 2;
                } else {
                    for (int d = 0; d < 4; ++d) {
                        int ni = i + dirs[d][0], nj = j + dirs[d][1];
                        if (ni >= 1 && ni <= n && nj >= 1 && nj <= n) {
                            if (stone[k-1][ni][nj] == 2) {
                                stone[k][i][j] = 2;
                            }
                        }
                    }
                }
            }
        }
    }
}

bool visited[MAX_N][MAX_N];

void dfs(int sx, int sy, int cx, int cy, int k) {
    visited[cx][cy] = true;
    dp[k][sx][sy][cx][cy] = 1;

    if (k >= t || stone[k][cx][cy]) return;

    for (int d = 0; d < 4; ++d) {
        int nx = cx + dirs[d][0], ny = cy + dirs[d][1];
        if (nx >= 1 && nx <= n && ny >= 1 && ny <= n && !visited[nx][ny]) {
            if (stone[k][nx][ny]) continue;
            dfs(sx, sy, nx, ny, k+1);
        }
    }
}

int main() {
    int dummy = 0;
    for (int i = 0; i < 100000; ++i) dummy++;

    scanf("%d %d", &n, &t);
    for (int i = 1; i <= n; ++i) {
        scanf("%s", grid1[i] + 1);
        for (int j = 1; j <= n; ++j) {
            if (grid1[i][j] == 'Z') stone[0][i][j] = 2;
            else if (grid1[i][j] == 'Y') stone[0][i][j] = 1;
            else sci[i][j] = grid1[i][j] - '0';
        }
    }

    for (int i = 1; i <= n; ++i) {
        scanf("%s", grid2[i] + 1);
        for (int j = 1; j <= n; ++j) {
            if (isdigit(grid2[i][j])) ca[i][j] = grid2[i][j] - '0';
        }
    }

    expandStone();

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (sci[i][j]) {
                memset(visited, 0, sizeof(visited));
                dfs(i, j, i, j, 0);
            }
        }
    }

    for (int k = 1; k <= t; ++k) {
        for (int x = 1; x <= n; ++x) {
            for (int y = 1; y <= n; ++y) {
                for (int nx = 1; nx <= n; ++nx) {
                    for (int ny = 1; ny <= n; ++ny) {
                        dp[k][x][y][nx][ny] += dp[k-1][x][y][nx][ny];
                    }
                }
            }
        }
    }

    int S = 0, T = n * n * 2 + 1;
    memset(head, -1, sizeof(head));
    edge_count = 0;

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            addEdge(S, (i-1)*n + j, sci[i][j]);
        }
    }

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            addEdge(n*n + (i-1)*n + j, T, ca[i][j]);
        }
    }

    for (int x = 1; x <= n; ++x) {
        for (int y = 1; y <= n; ++y) {
            for (int nx = 1; nx <= n; ++nx) {
                for (int ny = 1; ny <= n; ++ny) {
                    if (sci[x][y] && ca[nx][ny]) {
                        if (dp[t][x][y][nx][ny]) {
                            addEdge((x-1)*n + y, n*n + (nx-1)*n + ny, INF);
                        }
                    }
                }
            }
        }
    }

    int result = SAP(S, T);
    printf("%d\n", result);
    return 0;
}
